/// The branch style: how the map's boughs and nodes are drawn (widths as
/// fractions of the node diameter, knuckles, bark grain, hatching, leaves,
/// the nodes' sparkle per tier). The numbers come from the art kit's spec,
/// `assets/brand/branch-style.json` (generated by `app/tool/brand/make_tosk.py`
/// next to the reference SVGs); the defaults here equal that file, so the
/// painter matches the art even before the asset is read, and a regenerated
/// spec is followed without a code change.
library;

import 'dart:convert';

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart' show rootBundle;
import 'package:flutter_riverpod/flutter_riverpod.dart';

/// Where the art kit's spec lives.
const String kBranchStyleAsset = 'assets/brand/branch-style.json';

/// The reference node diameter of the spec (its nodes have r = 40): lengths
/// in px in the spec become fractions of the node diameter here.
const double _refDiameter = 80;

/// One twinkle (or dot) around a node: polar position in units of r,
/// [size] in units of r (a twinkle's tip distance, a dot's radius).
@immutable
class Sparkle {
  const Sparkle({required this.angle, required this.dist, required this.size, this.rotate = 0});

  /// Degrees, 0 = right, positive = clockwise on screen.
  final double angle;
  final double dist;
  final double size;
  final double rotate;

  static Sparkle? _from(Object? v) {
    if (v is! Map) return null;
    final m = v.cast<String, Object?>();
    final a = _num(m['angle']), d = _num(m['dist']), s = _num(m['size']);
    if (a == null || d == null || s == null) return null;
    return Sparkle(angle: a.toDouble(), dist: d.toDouble(), size: s.toDouble(), rotate: _num(m['rotate'])?.toDouble() ?? 0);
  }
}

/// Gold's rays: [count] short strokes from [r0] to [r1] (units of r).
@immutable
class Rays {
  const Rays({this.count = 8, this.startDeg = 22.5, this.r0 = 1.12, this.r1 = 1.32, this.width = 0.08});
  final int count;
  final double startDeg;
  final double r0;
  final double r1;
  final double width;

  static Rays? _from(Object? v) {
    if (v is! Map) return null;
    final m = v.cast<String, Object?>();
    const d = Rays();
    return Rays(
      count: _num(m['count'])?.toInt() ?? d.count,
      startDeg: _num(m['start_deg'])?.toDouble() ?? d.startDeg,
      r0: _num(m['r0'])?.toDouble() ?? d.r0,
      r1: _num(m['r1'])?.toDouble() ?? d.r1,
      width: _num(m['width'])?.toDouble() ?? d.width,
    );
  }
}

/// A tier's sparkle: twinkles, dots and (gold) rays.
@immutable
class TierSparkle {
  const TierSparkle({this.twinkles = const [], this.dots = const [], this.rays});
  final List<Sparkle> twinkles;
  final List<Sparkle> dots;
  final Rays? rays;

  static const none = TierSparkle();

  static const bronze = TierSparkle(twinkles: [Sparkle(angle: -52, dist: 1.24, size: 0.17)]);
  static const silver = TierSparkle(
    twinkles: [Sparkle(angle: -50, dist: 1.3, size: 0.24), Sparkle(angle: -152, dist: 1.26, size: 0.14, rotate: 15)],
    dots: [Sparkle(angle: -100, dist: 1.42, size: 0.035)],
  );
  static const gold = TierSparkle(
    twinkles: [
      Sparkle(angle: -48, dist: 1.42, size: 0.3),
      Sparkle(angle: -150, dist: 1.36, size: 0.19, rotate: 15),
      Sparkle(angle: 118, dist: 1.4, size: 0.15, rotate: 10),
      Sparkle(angle: 24, dist: 1.5, size: 0.12),
    ],
    dots: [
      Sparkle(angle: -100, dist: 1.56, size: 0.04),
      Sparkle(angle: 62, dist: 1.62, size: 0.035),
      Sparkle(angle: -14, dist: 1.72, size: 0.03),
    ],
    rays: Rays(),
  );

  static TierSparkle _from(Object? v, TierSparkle fallback) {
    if (v is! Map) return fallback;
    final m = v.cast<String, Object?>();
    List<Sparkle> list(Object? x) => x is List ? [for (final e in x) ?Sparkle._from(e)] : const [];
    return TierSparkle(
      twinkles: m.containsKey('twinkles') ? list(m['twinkles']) : fallback.twinkles,
      dots: m.containsKey('dots') ? list(m['dots']) : fallback.dots,
      rays: m.containsKey('rays') ? Rays._from(m['rays']) : fallback.rays,
    );
  }
}

/// The paper-coloured gleam arc on the metal tiers (units of r; degrees).
@immutable
class Gleam {
  const Gleam({this.radius = 0.56, this.from = -120, this.to = -40, this.width = 0.07, this.opacity = 0.75});
  final double radius;
  final double from;
  final double to;
  final double width;
  final double opacity;

  static Gleam _from(Object? v) {
    if (v is! Map) return const Gleam();
    final m = v.cast<String, Object?>();
    const d = Gleam();
    final arc = m['arc_deg'];
    return Gleam(
      radius: _num(m['radius'])?.toDouble() ?? d.radius,
      from: arc is List && arc.length == 2 ? (_num(arc[0])?.toDouble() ?? d.from) : d.from,
      to: arc is List && arc.length == 2 ? (_num(arc[1])?.toDouble() ?? d.to) : d.to,
      width: _num(m['width'])?.toDouble() ?? d.width,
      opacity: _num(m['opacity'])?.toDouble() ?? d.opacity,
    );
  }
}

@immutable
class BranchStyle {
  const BranchStyle({
    this.widthStart = 40 / _refDiameter,
    this.widthEnd = 12 / _refDiameter,
    this.lockedWidthScale = 0.75,
    this.knucklesMin = 1,
    this.knucklesMax = 2,
    this.knuckleCentre = const [0.25, 0.75],
    this.knuckleAmp = const [0.18, 0.38],
    this.knuckleSigma = const [0.05, 0.09],
    this.grainOffsets = const [0.18, 0.35, 0.52],
    this.grainDash = const [0.12, 0.32],
    this.grainGap = const [0.08, 0.28],
    this.grainWidth = 1.5,
    this.grainOpacity = 0.85,
    this.hatchSpacing = 6,
    this.hatchAngle = 70,
    this.hatchWidth = 1.0,
    this.hatchOpacity = 0.62,
    this.hatchInner = 0.12,
    this.hatchOuter = 0.65,
    this.outlineMin = 1.3,
    this.outlineMax = 4.2,
    this.wobble = 0.5,
    this.leafScale = 0.775,
    this.leafMinLength = 1.5,
    this.leafAt = 0.55,
    this.twigLength = const [40, 70],
    this.twigWidth = const [10, 4],
    this.sparkle = const {'bronze': TierSparkle.bronze, 'silver': TierSparkle.silver, 'gold': TierSparkle.gold},
    this.gleam = const Gleam(),
    this.extent = 1.75,
  });

  /// Bough width at the parent and at the child, as fractions of the node diameter.
  final double widthStart;
  final double widthEnd;

  /// Boughs to locked skills are thinner by this factor.
  final double lockedWidthScale;

  /// Knuckles: bumps where the bough swells (count range; centre, relative
  /// amplitude and sigma ranges, as fractions of the bough length).
  final int knucklesMin;
  final int knucklesMax;
  final List<double> knuckleCentre;
  final List<double> knuckleAmp;
  final List<double> knuckleSigma;

  /// Bark grain on the shadow side: dashed lines offset from the centre as
  /// fractions of the half width; dash and gap as fractions of the length.
  final List<double> grainOffsets;
  final List<double> grainDash;
  final List<double> grainGap;
  final double grainWidth;
  final double grainOpacity;

  /// Hatching on the shadow side, between [hatchInner] and [hatchOuter] of
  /// the half width, [hatchAngle] degrees off the bough direction.
  final double hatchSpacing;
  final double hatchAngle;
  final double hatchWidth;
  final double hatchOpacity;
  final double hatchInner;
  final double hatchOuter;

  /// Ink outline: thin on the lit side, heavy in the shadow; hand wobble in px.
  final double outlineMin;
  final double outlineMax;
  final double wobble;

  /// Leaves: a pinnate ash leaf on a twig off boughs at least [leafMinLength]
  /// node diameters long, [leafAt] of the way along. [leafScale] × the node
  /// diameter / 80 is the leaf's scale (the leaf is 92 px at scale 1).
  final double leafScale;
  final double leafMinLength;
  final double leafAt;

  /// Twig length range and widths (px at the reference size).
  final List<double> twigLength;
  final List<double> twigWidth;

  /// Sparkle per tier name (bronze, silver, gold).
  final Map<String, TierSparkle> sparkle;
  final Gleam gleam;

  /// How far sparkles reach beyond the node, in units of r.
  final double extent;

  static const defaults = BranchStyle();

  TierSparkle sparkleFor(String tier) => sparkle[tier] ?? TierSparkle.none;

  /// Reads the kit's `branch-style.json`; missing keys keep the defaults.
  factory BranchStyle.fromJson(Map<String, Object?> json) {
    const def = BranchStyle();
    final bough = _map(json['bough']);
    final knuckles = _map(bough['knuckles']);
    final grain = _map(bough['grain']);
    final hatch = _map(bough['hatch']);
    final twigs = _map(bough['twigs']);
    final outline = _map(json['ink_outline']);
    final leaves = _map(json['leaves']);
    final placement = _map(leaves['placement']);
    final nodes = _map(json['nodes']);
    final sparkle = _map(nodes['sparkle']);
    final widthMain = _pair(bough['width_main']);
    final leafScale = _pair(placement['scale']);
    final hatchAngle = hatch['angle'];
    return BranchStyle(
      widthStart: widthMain != null ? widthMain[0] / _refDiameter : def.widthStart,
      widthEnd: widthMain != null ? widthMain[1] / _refDiameter : def.widthEnd,
      lockedWidthScale: _num(bough['locked_width_scale'])?.toDouble() ?? def.lockedWidthScale,
      knucklesMin: _pair(knuckles['count'])?[0].toInt() ?? def.knucklesMin,
      knucklesMax: _pair(knuckles['count'])?[1].toInt() ?? def.knucklesMax,
      knuckleCentre: _pair(knuckles['centre']) ?? def.knuckleCentre,
      knuckleAmp: _pair(knuckles['amplitude']) ?? def.knuckleAmp,
      knuckleSigma: _pair(knuckles['sigma']) ?? def.knuckleSigma,
      grainOffsets: _list(grain['offsets'])?.map((v) => v.abs()).toList() ?? def.grainOffsets,
      grainDash: _pair(grain['dash_length']) ?? def.grainDash,
      grainGap: _pair(grain['gap']) ?? def.grainGap,
      grainWidth: _num(grain['stroke_width'])?.toDouble() ?? def.grainWidth,
      grainOpacity: _num(grain['opacity'])?.toDouble() ?? def.grainOpacity,
      hatchSpacing: _num(hatch['spacing'])?.toDouble() ?? def.hatchSpacing,
      hatchAngle: _num(hatchAngle)?.toDouble() ??
          (hatchAngle is String ? _num(RegExp(r'[-+]?\d+(\.\d+)?').allMatches(hatchAngle).lastOrNull?.group(0))?.toDouble() : null) ??
          def.hatchAngle,
      hatchWidth: _num(hatch['width'])?.toDouble() ?? def.hatchWidth,
      hatchOpacity: _num(hatch['opacity'])?.toDouble() ?? def.hatchOpacity,
      outlineMin: _num(outline['min_width'])?.toDouble() ?? def.outlineMin,
      outlineMax: _num(outline['max_width'])?.toDouble() ?? def.outlineMax,
      wobble: _num(outline['wobble_px'])?.toDouble() ?? def.wobble,
      leafScale: leafScale != null ? (leafScale[0] + leafScale[1]) / 2 : def.leafScale,
      twigLength: _pair(twigs['length']) ?? def.twigLength,
      twigWidth: _pair(bough['width_twig']) ?? def.twigWidth,
      sparkle: {
        for (final tier in const ['bronze', 'silver', 'gold'])
          tier: TierSparkle._from(sparkle[tier], def.sparkleFor(tier)),
      },
      gleam: nodes.containsKey('gleam') ? Gleam._from(nodes['gleam']) : def.gleam,
      extent: _num(nodes['extent'])?.toDouble() ?? def.extent,
    );
  }

  /// Parses the asset's JSON text; anything unparseable gives the defaults.
  static BranchStyle parse(String text) {
    try {
      final v = jsonDecode(text);
      if (v is Map) return BranchStyle.fromJson(v.cast<String, Object?>());
    } catch (_) {
      // Fall through to the defaults.
    }
    return defaults;
  }
}

Map<String, Object?> _map(Object? v) => v is Map ? v.cast<String, Object?>() : const {};

num? _num(Object? v) => v is num ? v : (v is String ? num.tryParse(v) : null);

List<double>? _list(Object? v) {
  if (v is! List) return null;
  final out = <double>[];
  for (final e in v) {
    final n = _num(e);
    if (n == null) return null;
    out.add(n.toDouble());
  }
  return out;
}

List<double>? _pair(Object? v) {
  final l = _list(v);
  return l != null && l.length == 2 ? l : null;
}

/// The branch style from `assets/brand/branch-style.json`, or the defaults
/// while loading or when the asset is absent.
final branchStyleAssetProvider = FutureProvider<BranchStyle>((ref) async {
  try {
    return BranchStyle.parse(await rootBundle.loadString(kBranchStyleAsset));
  } catch (_) {
    return BranchStyle.defaults;
  }
});

final branchStyleProvider = Provider<BranchStyle>(
  (ref) => ref.watch(branchStyleAssetProvider).value ?? BranchStyle.defaults,
);
